import{j as e,y as m,H as f,z as c,A as l,D as h}from"./radix-afe7350e.js";import{r as i}from"./vendor-b7b6560c.js";import{a as n}from"./index-e72fb1a7.js";import{C as g}from"./chevron-down-dd7bf43c.js";import{B as y,F as v}from"./Footer-81957e8a.js";import{C as o}from"./circle-help-4d05f9e6.js";import{N as w}from"./Navigation-735f5ecb.js";import{F as x}from"./FloatingActions-1007041b.js";import{S as b}from"./SEO-e4b06975.js";import"./utils-66ddbc96.js";import"./query-735ceddb.js";import"./message-circle-685d34eb.js";const A=h,d=i.forwardRef(({className:r,...s},t)=>e.jsx(m,{ref:t,className:n("border-b",r),...s}));d.displayName="AccordionItem";const p=i.forwardRef(({className:r,children:s,...t},a)=>e.jsx(f,{className:"flex",children:e.jsxs(c,{ref:a,className:n("flex flex-1 items-center justify-between py-4 font-medium transition-all hover:underline [&[data-state=open]>svg]:rotate-180",r),...t,children:[s,e.jsx(g,{className:"h-4 w-4 shrink-0 transition-transform duration-200"})]})}));p.displayName=c.displayName;const u=i.forwardRef(({className:r,children:s,...t},a)=>e.jsx(l,{ref:a,className:"overflow-hidden text-sm transition-all data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down",...t,children:e.jsx("div",{className:n("pb-4 pt-0",r),children:s})}));u.displayName=l.displayName;const O=()=>{const r=[{question:"Who is this DevOps training suitable for?",answer:"Our courses are designed for IT professionals, fresh graduates, software developers, system administrators and QA engineers looking to start or advance a DevOps career. Whether you want to learn Docker, Kubernetes, CI/CD or cloud platforms like AWS, Azure, and GCP, we have a course for your level. Basic computer skills are recommended but no prior DevOps experience is required for our foundation course."},{question:"What DevOps tools will I learn in this course?",answer:"You will get hands-on experience with industry-standard DevOps tools including Git, Jenkins, GitHub Actions, Docker, Kubernetes, Terraform, Ansible, ArgoCD, Prometheus, Grafana, and more. Depending on your course, you will also learn AWS services (EC2, S3, CodePipeline, ECS/EKS, CloudFormation) or Azure services (Azure Pipelines, ARM/Bicep, AKS)."},{question:"Will I get certifications after completing the program?",answer:"Yes! The program includes preparation for industry-recognized certifications including AWS Certified DevOps Engineer Professional, Microsoft Azure DevOps Engineer Expert (AZ-400), Certified Kubernetes Administrator (CKA), and FinOps Certified Practitioner. You will receive comprehensive exam preparation materials and practice tests."},{question:"What is the job placement support?",answer:"We offer 100% Job Assistance assistance with our network of partner companies including TCS, Infosys, Wipro, Accenture and more. Our dedicated placement team provides resume building, mock interviews, LinkedIn profile optimization and job referrals. Our graduates typically get placed within 2-4 months of course completion with salary packages of 8-15 LPA."},{question:"Can I attend DevOps classes while working full-time?",answer:"Absolutely! The program is designed for working professionals with just 1 hour of daily commitment on weekdays. All sessions are live online and recorded for 1 year access, so you can review materials at your convenience if you miss a live session."},{question:"What makes Cloud Binary different from other DevOps training institutes?",answer:"Cloud Binary stands out with trainers who have 16+ years of real industry experience, not just theoretical knowledge. Our courses cover multiple clouds (AWS, Azure, GCP), include real-world projects where you build production-grade CI/CD pipelines, and we provide 100% job assistance. We focus on practical skills that employers actually want."},{question:"What is the DevOps course fee and are EMI options available?",answer:"Course fees vary based on the program duration and level. Please contact our team at +91 93927 43006 or visit our enrollment page for current pricing. We offer flexible payment options to make the training accessible."},{question:"Do I need to know coding to learn DevOps?",answer:"Basic understanding of scripting (Shell, Python or PowerShell) is helpful but not mandatory. Our DevOps Foundation course starts from the basics and gradually builds up your skills. By the end, you will be comfortable writing automation scripts, Dockerfiles, Kubernetes manifests and Terraform configurations."}];return e.jsxs("section",{id:"faq",className:"relative py-16 md:py-24 overflow-hidden",children:[e.jsx("div",{className:"absolute inset-0 bg-gradient-to-b from-white via-blue-50/20 to-white"}),e.jsx("div",{className:"absolute inset-0 bg-[radial-gradient(circle_at_20%_30%,rgba(79,156,249,0.05),transparent_50%),radial-gradient(circle_at_80%_70%,rgba(14,165,233,0.05),transparent_50%)]"}),e.jsxs("div",{className:"container mx-auto px-4 relative z-10",children:[e.jsxs("div",{className:"text-center mb-12",children:[e.jsxs(y,{className:"mb-4 bg-gradient-to-r from-primary to-accent-teal text-white px-4 py-2",children:[e.jsx(o,{className:"w-4 h-4 mr-2 inline"}),"Have Questions?"]}),e.jsxs("h2",{className:"text-4xl md:text-5xl font-bold text-foreground mb-4",children:["Frequently Asked ",e.jsx("span",{className:"bg-gradient-to-r from-primary to-accent-teal bg-clip-text text-transparent",children:"Questions"})]}),e.jsx("p",{className:"text-muted-foreground text-lg md:text-xl max-w-3xl mx-auto leading-relaxed",children:"Common questions about our DevOps training courses"})]}),e.jsx("div",{className:"max-w-4xl mx-auto",children:e.jsx(A,{type:"single",collapsible:!0,className:"space-y-4",children:r.map((s,t)=>e.jsxs(d,{value:`item-${t}`,className:"bg-white border-0 rounded-xl shadow-lg hover:shadow-xl transition-all duration-300 overflow-hidden group",style:{animationDelay:`${t*.1}s`},children:[e.jsx("div",{className:"absolute inset-0 bg-gradient-to-r from-primary/5 to-accent-teal/5 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"}),e.jsx(p,{className:"text-left hover:no-underline px-6 py-5 relative",children:e.jsxs("div",{className:"flex items-start gap-4 pr-4",children:[e.jsx("div",{className:"w-8 h-8 rounded-lg bg-gradient-to-br from-primary to-accent-teal flex items-center justify-center flex-shrink-0 mt-1 group-hover:scale-110 transition-transform",children:e.jsx(o,{className:"w-5 h-5 text-white"})}),e.jsx("span",{className:"font-bold text-foreground text-base md:text-lg group-hover:text-primary transition-colors",children:s.question})]})}),e.jsx(u,{className:"text-muted-foreground leading-relaxed px-6 pb-6 pt-2 ml-12 text-sm md:text-base relative",children:s.answer})]},t))})})]})]})},D=()=>(i.useEffect(()=>{const r={"@context":"https://schema.org","@type":"FAQPage",mainEntity:[{"@type":"Question",name:"What is the course duration for DevOps training?",acceptedAnswer:{"@type":"Answer",text:"Our comprehensive DevOps Engineer certification program is 90 days long (approximately 12-13 weeks). The course includes 6 real-time projects, daily assignments, and covers AWS, Azure, Docker, Kubernetes, Terraform, CI/CD, Jenkins, GitOps, and more. We offer both weekday and weekend batches to accommodate working professionals."}},{"@type":"Question",name:"What are the course fees for DevOps training?",acceptedAnswer:{"@type":"Answer",text:"The DevOps Engineer certification course fee is ₹49,999. We offer flexible EMI options starting from ₹4,999 per month. The fee includes 1 Year  access to course materials, lab access, 6 real-time projects, interview preparation, resume building, and 100% Job Assistance assistance. Early bird discounts and referral offers are also available."}},{"@type":"Question",name:"Do you provide 100% Job Assistance assistance?",acceptedAnswer:{"@type":"Answer",text:"Yes! We provide 100% Job Assistance assistance which includes: Resume building and optimization, Mock interviews with industry experts, Direct company referrals to our 200+ hiring partners including Microsoft, Amazon, Google, TCS, Infosys, Wipro, Interview preparation and soft skills training, LinkedIn profile optimization, Salary negotiation guidance. 6000+ students have been successfully placed through our program."}},{"@type":"Question",name:"What is the eligibility for DevOps training?",acceptedAnswer:{"@type":"Answer",text:"Our DevOps training is open to: Fresh graduates (B.Tech, BCA, MCA, BSc IT), Working professionals looking for career change, System administrators, Manual testers, Support engineers, Anyone with basic computer knowledge. No prior programming experience is mandatory. We start from basics and gradually build advanced skills."}},{"@type":"Question",name:"Are the batches conducted online or offline?",acceptedAnswer:{"@type":"Answer",text:"We offer both online and offline training options at Cloud Binary Hyderabad. Online batches: Live instructor-led sessions via Zoom/MS Teams with screen sharing, Recorded sessions for revision, Online lab access 24/7. Offline batches: Conducted at our Hitech City, Hyderabad training center, Hands-on lab sessions with dedicated workstations, Small batch size for personalized attention. You can choose the mode that suits you best."}},{"@type":"Question",name:"What certifications will I get after completing the course?",acceptedAnswer:{"@type":"Answer",text:"After successful completion, you will receive: 1. Cloud Binary DevOps Engineer Certification (Course completion certificate), 2. We prepare you for these industry certifications: AWS Certified DevOps Engineer - Professional, Azure DevOps Engineer Expert (AZ-400), Certified Kubernetes Administrator (CKA), Docker Certified Associate (DCA), FinOps Certified Practitioner (for FinOps course). Our certification pass rate is 92%."}},{"@type":"Question",name:"What is the average salary after DevOps training?",acceptedAnswer:{"@type":"Answer",text:"Based on our placement data: Freshers: ₹4-7 LPA, 1-3 years experience: ₹8-12 LPA, 3-5 years experience: ₹12-18 LPA, 5+ years experience: ₹18-30 LPA. Our students have achieved an average salary increase of 120%. Top performers have been placed at ₹25-35 LPA in companies like Microsoft, Amazon, and Google."}},{"@type":"Question",name:"What is FinOps and why should I learn it?",acceptedAnswer:{"@type":"Answer",text:"FinOps (Financial Operations) is the practice of bringing financial accountability to cloud spending. It's one of the fastest-growing roles in cloud computing. Why learn FinOps: High demand - Every cloud-using company needs FinOps specialists, High salaries - FinOps professionals earn ₹10-20 LPA average, Low competition - Very few trained professionals available, Future-proof career - Cloud spending is growing 40% yearly. Our FinOps certification aligns with Linux Foundation's FinOps Certified Practitioner exam."}},{"@type":"Question",name:"Do you provide lab access for practice?",acceptedAnswer:{"@type":"Answer",text:"Yes! Every student gets: 24/7 access to our cloud labs (AWS, Azure, GCP), Pre-configured environments for Docker, Kubernetes, Jenkins, Terraform, Real-world project repositories on GitHub, Access to premium DevOps tools, Lab access continues for 6 months post-course completion. You can practice anytime from anywhere with internet connection."}},{"@type":"Question",name:"Who are the trainers at Cloud Binary?",acceptedAnswer:{"@type":"Answer",text:"Our trainers are industry experts with 16+ years of experience working in companies like Microsoft, Amazon, Google, IBM, Accenture. They are: Certified professionals (AWS, Azure, Kubernetes, CNCF), Working DevOps architects and SRE leads, Active contributors to open-source projects, Experienced in training 6000+ students. All sessions include real-world scenarios and industry best practices learned from production environments."}}]};let s=document.querySelector('script[type="application/ld+json"][data-schema="faq"]');return s||(s=document.createElement("script"),s.setAttribute("type","application/ld+json"),s.setAttribute("data-schema","faq"),document.head.appendChild(s)),s.textContent=JSON.stringify(r),()=>{const t=document.querySelector('script[type="application/ld+json"][data-schema="faq"]');t&&t.remove()}},[]),null),q=()=>e.jsxs(e.Fragment,{children:[e.jsx(b,{title:"FAQs - DevOps Training Course Fees, Duration, Placement, Certification | Cloud Binary Hyderabad",description:"Get All Your Questions Answered! DevOps Course Fees, Batch Timings, Eligibility, Placement Process, Certification Details, Job Guarantee, EMI Options, Weekend Batches, Online vs Offline, Syllabus, Prerequisites, Tools Covered, Trainer Experience, Lab Access, Project Details. Contact +91 93927 43006",keywords:"DevOps training fees Hyderabad, DevOps course duration, DevOps placement support, DevOps certification details, DevOps course eligibility, DevOps batch timings, DevOps weekend batch, DevOps EMI options, DevOps job guarantee, DevOps course FAQ, AWS training fees, Azure course cost, Kubernetes training duration, DevOps online training, DevOps offline classes, DevOps prerequisites, DevOps syllabus, DevOps projects"}),e.jsx(D,{}),e.jsx(w,{}),e.jsx("main",{className:"min-h-screen bg-white",children:e.jsx(O,{})}),e.jsx(v,{}),e.jsx(x,{})]});export{q as default};
